using System.Net.Http.Json;
using System.Text.Json;

namespace Arrk.Bazarr;

/// <summary>
/// Typed HTTP client for the Bazarr API. Bazarr requires its own API key on every call; the key is
/// generated by Bazarr itself, so <see cref="BazarrApiKeyStore"/> reads it from the container's
/// config file and this client injects it per request.
/// </summary>
public sealed class BazarrClient
{
    public static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web)
    {
        PropertyNameCaseInsensitive = true
    };

    readonly HttpClient _http;
    readonly Func<CancellationToken, Task<string?>> _apiKey;

    public BazarrClient(string url, Func<CancellationToken, Task<string?>> apiKey, HttpMessageHandler? handler = null)
    {
        _apiKey = apiKey;
        _http = handler is null ? new HttpClient() : new(handler, disposeHandler: false);
        _http.BaseAddress = new Uri(url.EndsWith('/') ? url : url + "/");
        _http.Timeout = TimeSpan.FromSeconds(60);
    }

    public async Task<bool> IsAvailableAsync(CancellationToken ct = default)
    {
        try
        {
            await GetSystemStatusAsync(ct);
            return true;
        }
        catch
        {
            return false;
        }
    }

    public async Task<BazarrSystemStatus> GetSystemStatusAsync(CancellationToken ct = default)
    {
        BazarrEnvelope<BazarrSystemStatus> envelope =
            await GetAsync<BazarrEnvelope<BazarrSystemStatus>>("api/system/status", ct);
        return envelope.Data;
    }

    public async Task<List<BazarrMovie>> GetMoviesAsync(IEnumerable<int> ids, CancellationToken ct = default)
    {
        string query = Query("api/movies", "radarrid[]", ids);
        BazarrEnvelope<List<BazarrMovie>> envelope =
            await GetAsync<BazarrEnvelope<List<BazarrMovie>>>(query, ct);
        return envelope.Data ?? [];
    }

    public async Task<List<BazarrSeries>> GetSeriesAsync(IEnumerable<int> ids, CancellationToken ct = default)
    {
        string query = Query("api/series", "seriesid[]", ids);
        BazarrEnvelope<List<BazarrSeries>> envelope =
            await GetAsync<BazarrEnvelope<List<BazarrSeries>>>(query, ct);
        return envelope.Data ?? [];
    }

    public async Task<List<BazarrLanguage>> GetLanguagesAsync(CancellationToken ct = default)
    {
        List<BazarrLanguage>? languages =
            await GetAsync<List<BazarrLanguage>>("api/system/languages", ct);
        return languages ?? [];
    }

    public async Task<List<BazarrEpisode>> GetEpisodesAsync(
        IEnumerable<int>? seriesIds = null,
        IEnumerable<int>? episodeIds = null,
        CancellationToken ct = default)
    {
        List<string> query = [];
        if (episodeIds is not null)
            query.AddRange(episodeIds.Select(id => $"episodeid[]={id}"));
        if (seriesIds is not null)
            query.AddRange(seriesIds.Select(id => $"seriesid[]={id}"));

        string path = query.Count == 0 ? "api/episodes" : "api/episodes?" + string.Join('&', query);
        BazarrEnvelope<List<BazarrEpisode>> envelope =
            await GetAsync<BazarrEnvelope<List<BazarrEpisode>>>(path, ct);
        return envelope.Data ?? [];
    }

    public async Task<List<BazarrProviderCandidate>> SearchMovieAsync(int radarrId, CancellationToken ct = default)
    {
        BazarrEnvelope<List<BazarrProviderCandidate>> envelope =
            await GetAsync<BazarrEnvelope<List<BazarrProviderCandidate>>>(
                $"api/providers/movies?radarrid={radarrId}", ct);
        return envelope.Data ?? [];
    }

    public async Task<List<BazarrProviderCandidate>> SearchEpisodeAsync(
        int episodeId,
        CancellationToken ct = default)
    {
        BazarrEnvelope<List<BazarrProviderCandidate>> envelope =
            await GetAsync<BazarrEnvelope<List<BazarrProviderCandidate>>>(
                $"api/providers/episodes?episodeid={episodeId}", ct);
        return envelope.Data ?? [];
    }

    public async Task DownloadMovieSubtitleAsync(
        int radarrId,
        BazarrProviderCandidate candidate,
        CancellationToken ct = default)
    {
        Dictionary<string, string> fields = new()
        {
            ["radarrid"] = radarrId.ToString(),
            ["hi"] = candidate.HearingImpaired,
            ["forced"] = candidate.Forced,
            ["original_format"] = candidate.OriginalFormat,
            ["provider"] = candidate.Provider,
            ["subtitle"] = candidate.Subtitle
        };
        await PostFormAsync("api/providers/movies", fields, ct);
    }

    public async Task DownloadEpisodeSubtitleAsync(
        int seriesId,
        int episodeId,
        BazarrProviderCandidate candidate,
        CancellationToken ct = default)
    {
        Dictionary<string, string> fields = new()
        {
            ["seriesid"] = seriesId.ToString(),
            ["episodeid"] = episodeId.ToString(),
            ["hi"] = candidate.HearingImpaired,
            ["forced"] = candidate.Forced,
            ["original_format"] = candidate.OriginalFormat,
            ["provider"] = candidate.Provider,
            ["subtitle"] = candidate.Subtitle
        };
        await PostFormAsync("api/providers/episodes", fields, ct);
    }

    public async Task SearchMissingMovieAsync(int radarrId, CancellationToken ct = default)
    {
        await PatchFormAsync("api/movies", new Dictionary<string, string>
        {
            ["radarrid"] = radarrId.ToString(),
            ["action"] = "search-missing"
        }, ct);
    }

    public async Task SearchMissingSeriesAsync(int seriesId, CancellationToken ct = default)
    {
        await PatchFormAsync("api/series", new Dictionary<string, string>
        {
            ["seriesid"] = seriesId.ToString(),
            ["action"] = "search-missing"
        }, ct);
    }

    public async Task AssignMovieProfileAsync(
        IEnumerable<int> movieIds,
        int profileId,
        CancellationToken ct = default)
    {
        List<int> ids = movieIds.ToList();
        if (ids.Count == 0)
            return;

        Dictionary<string, List<string>> fields = new()
        {
            ["radarrid"] = ids.Select(id => id.ToString()).ToList(),
            ["profileid"] = ids.Select(_ => profileId.ToString()).ToList()
        };
        await PostMultiFormAsync("api/movies", fields, ct);
    }

    public async Task AssignSeriesProfileAsync(
        IEnumerable<int> seriesIds,
        int profileId,
        CancellationToken ct = default)
    {
        List<int> ids = seriesIds.ToList();
        if (ids.Count == 0)
            return;

        Dictionary<string, List<string>> fields = new()
        {
            ["seriesid"] = ids.Select(id => id.ToString()).ToList(),
            ["profileid"] = ids.Select(_ => profileId.ToString()).ToList()
        };
        await PostMultiFormAsync("api/series", fields, ct);
    }

    public async Task UpdateSettingsAsync(
        IReadOnlyList<KeyValuePair<string, string>> fields,
        CancellationToken ct = default)
    {
        using FormUrlEncodedContent content = new(fields);
        using HttpResponseMessage response = await SendAsync(HttpMethod.Post, "api/system/settings", content, ct);
        response.EnsureSuccessStatusCode();
    }

    /// <summary>
    /// Replaces Bazarr's language profile list. The settings endpoint treats the posted list as
    /// authoritative and deletes profiles that are not included, so callers must post every profile
    /// they want to keep.
    /// </summary>
    public async Task UpdateProfilesAsync(
        IReadOnlyList<BazarrLanguageProfile> profiles,
        CancellationToken ct = default)
    {
        string json = JsonSerializer.Serialize(profiles, JsonOptions);
        await UpdateSettingsAsync([new KeyValuePair<string, string>("languages-profiles", json)], ct);
    }

    public async Task TriggerTaskAsync(string taskId, CancellationToken ct = default)
    {
        using FormUrlEncodedContent content = new([new KeyValuePair<string, string>("taskid", taskId)]);
        using HttpResponseMessage response = await SendAsync(HttpMethod.Post, "api/system/tasks", content, ct);
        response.EnsureSuccessStatusCode();
    }

    /// <summary>Clears Bazarr's provider throttle state after the provider list or credentials change.</summary>
    public async Task ResetProvidersAsync(CancellationToken ct = default)
    {
        using FormUrlEncodedContent content = new([new KeyValuePair<string, string>("action", "reset")]);
        using HttpResponseMessage response = await SendAsync(HttpMethod.Post, "api/providers", content, ct);
        response.EnsureSuccessStatusCode();
    }

    public async Task<List<BazarrLanguageProfile>> GetLanguageProfilesAsync(CancellationToken ct = default)
    {
        List<BazarrLanguageProfile> profiles =
            await GetAsync<List<BazarrLanguageProfile>>("api/system/languages/profiles", ct);
        return profiles ?? [];
    }

    async Task<T> GetAsync<T>(string path, CancellationToken ct)
    {
        using HttpResponseMessage response = await SendAsync(HttpMethod.Get, path, content: null, ct);
        response.EnsureSuccessStatusCode();
        T? value = await response.Content.ReadFromJsonAsync<T>(JsonOptions, ct);
        if (value is null)
            throw new InvalidOperationException($"Bazarr returned an empty response for {path}.");
        return value;
    }

    async Task PostFormAsync(string path, IReadOnlyDictionary<string, string> fields, CancellationToken ct)
    {
        using FormUrlEncodedContent content = new(fields);
        using HttpResponseMessage response = await SendAsync(HttpMethod.Post, path, content, ct);
        response.EnsureSuccessStatusCode();
    }

    async Task PostMultiFormAsync(
        string path,
        IReadOnlyDictionary<string, List<string>> fields,
        CancellationToken ct)
    {
        List<KeyValuePair<string, string>> values = [];
        foreach (KeyValuePair<string, List<string>> field in fields)
        {
            foreach (string value in field.Value)
                values.Add(new(field.Key, value));
        }

        using FormUrlEncodedContent content = new(values);
        using HttpResponseMessage response = await SendAsync(HttpMethod.Post, path, content, ct);
        response.EnsureSuccessStatusCode();
    }

    async Task PatchFormAsync(string path, IReadOnlyDictionary<string, string> fields, CancellationToken ct)
    {
        using FormUrlEncodedContent content = new(fields);
        using HttpResponseMessage response = await SendAsync(HttpMethod.Patch, path, content, ct);
        response.EnsureSuccessStatusCode();
    }

    async Task<HttpResponseMessage> SendAsync(
        HttpMethod method,
        string path,
        HttpContent? content,
        CancellationToken ct)
    {
        using HttpRequestMessage request = new(method, path);
        string? apiKey = await _apiKey(ct);
        if (!string.IsNullOrWhiteSpace(apiKey))
            request.Headers.TryAddWithoutValidation("X-API-KEY", apiKey);
        request.Content = content;

        return await _http.SendAsync(request, ct);
    }

    static string Query(string path, string key, IEnumerable<int> ids)
    {
        List<string> values = ids.Select(id => $"{key}={id}").ToList();
        return values.Count == 0 ? path : path + "?" + string.Join('&', values);
    }
}
